// Package markdown is a modular, incremental Markdown renderer for the port's
// terminal UI. It is built from the ground up rather than ported from Marked:
// the block lexer, inline parser, layout and renderer are separate stages over
// a small document model, and none of them uses regexp (the previous lexer
// called a dozen compiled regexes per line, which is where its throughput went).
//
// Feature parity target: every construct in tui/testdata/md_corpus.json, whose
// golden is generated by Marked (the parser upstream markdown.ts calls). The
// mdgolden_test.go differential harness projects this package's model into the
// same JSON and compares.
//
// The model keeps each top-level block's byte range so the lexer can be driven
// incrementally: appending to a source reuses the blocks before the trailing
// open block and re-lexes only the tail.
package markdown

// BlockKind identifies a block-level element.
type BlockKind uint8

const (
	BlockParagraph BlockKind = iota
	BlockHeading
	BlockCode
	BlockQuote
	BlockList
	BlockListItem
	BlockThematicBreak
	BlockTable
	BlockHTML
	BlockLatex
	BlockSpace
)

// Block is a block-level element. Blocks form a tree: BlockQuote and BlockList
// carry children (BlockList's children are BlockListItem-shaped Blocks).
type Block struct {
	Kind BlockKind

	// Start and End are byte offsets into the source. End is exclusive and
	// covers the block's raw text including its trailing newline.
	Start int
	End   int

	// Raw is the block's source text where the projection needs it (code,
	// html, latex). It is empty when the source slice is not retained.
	Raw string

	// Level is an ATX/setext heading level (1-6).
	Level int
	// Info is a fenced code block's info string (language).
	Info string
	// Body is a code block's text.
	Body string
	// Text is a paragraph's or heading's inline source, a table cell's text, a
	// blockquote's stripped inner source, or a list item's content source.
	Text string
	// Inlines is the parsed inline content of Text.
	Inlines []Inline

	// Blocks are a quote's or list item's children.
	Blocks []*Block

	// List fields.
	Ordered     bool
	StartNumber int
	Tight       bool

	// Table fields: Align per column, Header cells, Rows of cells.
	Align  []Align
	Header []string
	Rows   [][]string
	// headerInlines and rowInlines are filled by ParseInlines.
	headerInlines [][]Inline
	rowInlines    [][][]Inline

	// Task marks a task-list item's checkbox state and Checked its state.
	Task    bool
	Checked bool
}

// Align is a table column alignment.
type Align uint8

const (
	AlignNone Align = iota
	AlignLeft
	AlignCenter
	AlignRight
)

// alignmentName returns the golden's alignment string, or "" for none.
func (a Align) name() string {
	switch a {
	case AlignLeft:
		return "left"
	case AlignCenter:
		return "center"
	case AlignRight:
		return "right"
	}
	return ""
}

// InlineKind identifies an inline element.
type InlineKind uint8

const (
	InlineText InlineKind = iota
	InlineCode
	InlineStrong
	InlineEmphasis
	InlineStrikethrough
	InlineLink
	InlineImage
	InlineHardBreak
	InlineEscape
	InlineHTML
	InlineLatex
	InlineCheckbox
)

// Inline is an inline element.
type Inline struct {
	Kind InlineKind
	// Text is the literal for text, code and html, the target text for a
	// checkbox, or the inner source for emphasis, strong, strikethrough, links
	// and images.
	Text string
	// Raw is the source spelling for escape and latex inlines.
	Raw string
	// Children are the nested inlines for emphasis, strong, strikethrough,
	// links and images.
	Children []Inline
	// Dest and Title are a link's or image's destination and title.
	Dest  string
	Title string
}
